(function () {
	"use strict";
	// ============================================
	// HERO SLIDER MODERNIZADO - SIN BLINKS
	// ============================================
	const imageWrapper = document.querySelector(".hero-section__image-wrapper");
	if (!imageWrapper) return;
	const slider = document.querySelector(".hero-section__slider");
	const slides = document.querySelectorAll(".hero-section__slide");
	const badge = document.querySelector(".hero-section__car-badge");
	// Elementos del badge
	const badgeLogoImg = badge
		? badge.querySelector(".hero-section__car-logo img")
		: null;
	const badgeTitle = badge
		? badge.querySelector(".hero-section__car-title")
		: null;
	const badgeSubtitle = badge
		? badge.querySelector(".hero-section__car-subtitle")
		: null;
	const badgePrice = badge
		? badge.querySelector(".hero-section__car-price")
		: null;
	const badgeCta = badge ? badge.querySelector(".hero-section__car-cta") : null;
	// Controles
	const btnPrev = document.querySelector(".hero-section__slider-btn--prev");
	const btnNext = document.querySelector(".hero-section__slider-btn--next");
	const btnToggle = document.querySelector(".hero-section__slider-toggle");
	const dots = badge
		? Array.from(badge.querySelectorAll(".hero-section__dot"))
		: [];
	// Datos de coches
	let cars = [];
	try {
		cars = JSON.parse(imageWrapper.getAttribute("data-hero-cars") || "[]");
	} catch (e) {
		console.warn("Error parsing hero cars data:", e);
		cars = [];
	}
	// Estado del slider
	let currentIndex = 0;
	let timer = null;
	let isPaused = false;
	let isTransitioning = false;
	// Configuración
	const DEFAULT_INTERVAL = 6000;
	const HOVER_INTERVAL = 4000;
	const TRANSITION_DURATION = 1000;
	// ============================================
	// FUNCIONES PRINCIPALES
	// ============================================
	function safeText(el, text) {
		if (!el) return;
		el.textContent = (text || "").toString();
	}
	function setToggleIcon(paused) {
		if (!btnToggle) return;
		btnToggle.setAttribute("aria-pressed", paused ? "true" : "false");
		btnToggle.setAttribute(
			"aria-label",
			paused ? "Reanudar reproducción" : "Pausar reproducción",
		);
		const svg = btnToggle.querySelector("svg");
		if (!svg) return;
		if (paused) {
			svg.innerHTML = '<path d="M8 5v14l11-7z"></path>';
		} else {
			svg.innerHTML = '<path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"></path>';
		}
	}
	function animateBadge() {
		if (!badge) return;
		badge.classList.remove("is-animating");
		void badge.offsetWidth; // Trigger reflow
		badge.classList.add("is-animating");
	}
	function updateDots(activeIndex) {
		if (!dots.length) return;
		dots.forEach((dot, i) => {
			dot.setAttribute("aria-current", i === activeIndex ? "true" : "false");
		});
	}
	function preloadImage(src) {
		if (!src) return;
		const img = new Image();
		img.decoding = "async";
		img.fetchPriority = "low";
		img.src = src;
	}
	function updateBadge(car) {
		if (!badge) return;
		const marcaModelo = [car?.marca, car?.modelo].filter(Boolean).join(" ");
		const version = car?.version ? car.version : "";
		const price = car?.precio ? car.precio : "";
		safeText(badgeTitle, marcaModelo || "Vehículo destacado");
		safeText(badgeSubtitle, version);
		safeText(badgePrice, price);
		if (badgeCta) {
			badgeCta.href = car?.link ? car.link : "#";
			badgeCta.setAttribute(
				"aria-label",
				car?.link ? "Ver ficha del vehículo" : "Ver vehículos",
			);
		}
		if (badgeLogoImg) {
			if (car?.logo) {
				badgeLogoImg.src = car.logo;
				badgeLogoImg.alt = car?.marca
					? "Logo de " + car.marca
					: "Logo de marca";
				badgeLogoImg.style.display = "block";
			} else {
				badgeLogoImg.src = "";
				badgeLogoImg.alt = "";
				badgeLogoImg.style.display = "none";
			}
		}
		animateBadge();
	}
	// Función principal para cambiar slides - OPTIMIZADA
	function setActiveSlide(nextIndex) {
		if (isTransitioning || !slides.length || !cars.length) return;
		isTransitioning = true;
		const prevIndex = currentIndex;
		const prevSlide = slides[prevIndex];
		const nextSlide = slides[nextIndex];
		if (!nextSlide || nextIndex === prevIndex) {
			isTransitioning = false;
			return;
		}
		// Pre-transition: preparar nuevos z-index
		prevSlide.style.zIndex = "2";
		nextSlide.style.zIndex = "3";
		// Activar nuevo slide
		nextSlide.classList.add("is-active");
		nextSlide.classList.remove("is-exiting");
		// Desactivar slide anterior
		prevSlide.classList.add("is-exiting");
		prevSlide.classList.remove("is-active");
		// Actualizar estado
		currentIndex = nextIndex;
		// Actualizar UI
		updateDots(nextIndex);
		updateBadge(cars[nextIndex]);
		// Preload siguiente imagen
		const nextCar = cars[(nextIndex + 1) % cars.length];
		if (nextCar?.img) {
			setTimeout(() => preloadImage(nextCar.img), 500);
		}
		// Limpiar después de la transición
		setTimeout(() => {
			if (prevSlide) {
				prevSlide.classList.remove("is-exiting");
				prevSlide.style.zIndex = "1";
			}
			nextSlide.style.zIndex = "3";
			isTransitioning = false;
		}, TRANSITION_DURATION);
	}
	function goTo(index) {
		if (!cars.length || !slides.length) return;
		const max = Math.min(slides.length, cars.length);
		const safeIndex = (index + max) % max;
		setActiveSlide(safeIndex);
	}
	function nextSlide() {
		if (isPaused || isTransitioning) return;
		goTo(currentIndex + 1);
	}
	function stopAuto() {
		if (timer) {
			clearInterval(timer);
			timer = null;
		}
	}
	function startAuto(intervalMs) {
		stopAuto();
		if (!cars.length || slides.length <= 1) return;
		if (isPaused) return;
		timer = setInterval(nextSlide, intervalMs || DEFAULT_INTERVAL);
	}
	function setPaused(paused) {
		isPaused = !!paused;
		setToggleIcon(isPaused);
		if (isPaused) {
			stopAuto();
		} else {
			startAuto(DEFAULT_INTERVAL);
		}
	}
	// ============================================
	// INICIALIZACIÓN
	// ============================================
	function initSlider() {
		if (cars.length) {
			// Configurar estado inicial
			slides.forEach((slide, i) => {
				slide.classList.toggle("is-active", i === 0);
				slide.classList.remove("is-exiting");
				slide.style.zIndex = i === 0 ? "3" : "1";
			});
			currentIndex = 0;
			updateDots(0);
			updateBadge(cars[0]);
			setToggleIcon(false);
			// Preload de la siguiente imagen
			if (cars[1]?.img) {
				setTimeout(() => preloadImage(cars[1].img), 1000);
			}
			// Iniciar autoplay con retraso para que cargue la página
			setTimeout(() => startAuto(DEFAULT_INTERVAL), 1500);
		} else {
			// Sin coches: ocultar controles
			if (badge) badge.style.display = "none";
			if (btnToggle) btnToggle.style.display = "none";
			if (btnPrev) btnPrev.style.display = "none";
			if (btnNext) btnNext.style.display = "none";
		}
	}
	// ============================================
	// EVENT LISTENERS
	// ============================================
	// Navegación
	if (btnPrev) {
		btnPrev.addEventListener("click", (e) => {
			e.preventDefault();
			if (isTransitioning) return;
			const wasPaused = isPaused;
			goTo(currentIndex - 1);
			if (!wasPaused) startAuto(DEFAULT_INTERVAL);
		});
	}
	if (btnNext) {
		btnNext.addEventListener("click", (e) => {
			e.preventDefault();
			if (isTransitioning) return;
			const wasPaused = isPaused;
			goTo(currentIndex + 1);
			if (!wasPaused) startAuto(DEFAULT_INTERVAL);
		});
	}
	// Play/Pause
	if (btnToggle) {
		btnToggle.addEventListener("click", (e) => {
			e.preventDefault();
			setPaused(!isPaused);
		});
	}
	// Dots
	if (dots.length) {
		dots.forEach((dot) => {
			dot.addEventListener("click", (e) => {
				e.preventDefault();
				if (isTransitioning) return;
				const index = parseInt(dot.getAttribute("data-dot-index"), 10);
				if (!isNaN(index)) {
					const wasPaused = isPaused;
					goTo(index);
					if (!wasPaused) startAuto(DEFAULT_INTERVAL);
				}
			});
		});
	}
	// Hover effects
	if (imageWrapper) {
		let hoverTimer;
		imageWrapper.addEventListener("mouseenter", () => {
			clearTimeout(hoverTimer);
			if (!isPaused) {
				hoverTimer = setTimeout(() => startAuto(HOVER_INTERVAL), 150);
			}
		});
		imageWrapper.addEventListener("mouseleave", () => {
			clearTimeout(hoverTimer);
			if (!isPaused) {
				startAuto(DEFAULT_INTERVAL);
			}
		});
	}
	// Navegación por teclado
	if (slider) {
		slider.addEventListener("keydown", (e) => {
			if (!cars.length || isTransitioning) return;
			switch (e.key) {
				case "ArrowLeft":
					e.preventDefault();
					const wasPaused = isPaused;
					goTo(currentIndex - 1);
					if (!wasPaused) startAuto(DEFAULT_INTERVAL);
					break;
				case "ArrowRight":
					e.preventDefault();
					const wasPaused2 = isPaused;
					goTo(currentIndex + 1);
					if (!wasPaused2) startAuto(DEFAULT_INTERVAL);
					break;
				case " ":
				case "Spacebar":
					e.preventDefault();
					setPaused(!isPaused);
					break;
			}
		});
	}
	// ============================================
	// SCROLL INDICATOR
	// ============================================
	const scrollButton = document.querySelector(
		".hero-section__scroll-indicator",
	);
	const heroSection = document.querySelector(".hero-section");
	const featuredServices = document.querySelector(".featured-services");
	if (scrollButton && heroSection && featuredServices) {
		let isAnimating = false;
		let lastScrollY = window.scrollY;
		let scrollTimeout;
		const scrollThreshold = 100;
		const heroHeight = heroSection.offsetHeight;
		const featuredServicesTop = featuredServices.offsetTop;
		function updateScrollButton() {
			const scrollY = window.scrollY;
			const isAtTop = scrollY < scrollThreshold;
			const isPastHero = scrollY > heroHeight * 0.7;
			if (Math.abs(lastScrollY - scrollY) < 10) return;
			lastScrollY = scrollY;
			if (isAtTop) {
				scrollButton.classList.remove("scroll-up", "hidden");
				scrollButton.setAttribute(
					"aria-label",
					"Desplazar hacia abajo para ver más contenido",
				);
				const icon = scrollButton.querySelector("svg");
				if (icon) {
					icon.innerHTML =
						'<path d="M7.41 8.59L12 13.17l4.59-4.58L18 10l-6 6-6-6 1.41-1.41z" />';
				}
			} else if (isPastHero) {
				scrollButton.classList.remove("hidden");
				scrollButton.classList.add("scroll-up");
				scrollButton.setAttribute("aria-label", "Volver arriba");
				const icon = scrollButton.querySelector("svg");
				if (icon) {
					icon.innerHTML =
						'<path d="M7.41 15.41L12 10.83l4.59 4.58L18 14l-6-6-6 6z" />';
				}
			} else {
				scrollButton.classList.add("hidden");
				scrollButton.classList.remove("scroll-up");
			}
		}
		function smoothScroll(targetPosition, duration = 800) {
			if (isAnimating) return;
			isAnimating = true;
			const startPosition = window.scrollY;
			const distance = targetPosition - startPosition;
			let startTime = null;
			const easeInOutCubic = (t) =>
				t < 0.5 ? 4 * t * t * t : (t - 1) * (2 * t - 2) * (2 * t - 2) + 1;
			function animation(currentTime) {
				if (startTime === null) startTime = currentTime;
				const timeElapsed = currentTime - startTime;
				const progress = Math.min(timeElapsed / duration, 1);
				const easeProgress = easeInOutCubic(progress);
				window.scrollTo(0, startPosition + distance * easeProgress);
				if (timeElapsed < duration) {
					requestAnimationFrame(animation);
				} else {
					isAnimating = false;
					updateScrollButton();
				}
			}
			requestAnimationFrame(animation);
		}
		scrollButton.addEventListener("click", function (e) {
			e.preventDefault();
			if (scrollButton.classList.contains("scroll-up")) {
				smoothScroll(0);
			} else {
				const targetPosition = featuredServicesTop - 80;
				smoothScroll(targetPosition);
			}
			const icon = this.querySelector("svg");
			if (icon) {
				icon.style.transform = "scale(0.8)";
				setTimeout(() => {
					icon.style.transform = "";
				}, 200);
			}
		});
		function handleScroll() {
			clearTimeout(scrollTimeout);
			scrollTimeout = setTimeout(updateScrollButton, 20);
		}
		window.addEventListener("scroll", handleScroll);
		updateScrollButton();
	}
	// ============================================
	// INTERSECTION OBSERVER PARA ANIMACIONES
	// ============================================
	const serviceCards = document.querySelectorAll(".service-card");
	if ("IntersectionObserver" in window && serviceCards.length) {
		const cardObserver = new IntersectionObserver(
			(entries) => {
				entries.forEach((entry) => {
					if (entry.isIntersecting) {
						entry.target.style.animationPlayState = "running";
						cardObserver.unobserve(entry.target);
					}
				});
			},
			{
				threshold: 0.05,
				rootMargin: "0px 0px -50px 0px",
			},
		);
		serviceCards.forEach((card) => {
			cardObserver.observe(card);
		});
	}
	// ============================================
	// INICIALIZACIÓN Y LIMPIEZA
	// ============================================
	if (document.readyState === "loading") {
		document.addEventListener("DOMContentLoaded", initSlider);
	} else {
		setTimeout(initSlider, 100);
	}
	window.addEventListener("beforeunload", stopAuto);
	window.addEventListener("pagehide", stopAuto);
	document.addEventListener("visibilitychange", () => {
		if (document.hidden) {
			setPaused(true);
		} else if (!isPaused) {
			startAuto(DEFAULT_INTERVAL);
		}
	});
})();